add_action( 'woocommerce_before_cart', 'perfectpixel_message_if_category_in_cart' );

/**
 * Whether the cart contains a product from any of the given category slugs (sub-categories included).
 */
function perfectpixel_cart_has_category( $slugs ) {
	if ( ! WC()->cart ) {
		return false;
	}
	$term_ids = array();
	foreach ( (array) $slugs as $slug ) {
		$term = get_term_by( 'slug', $slug, 'product_cat' );
		if ( $term ) {
			$term_ids[] = $term->term_id;
			$term_ids   = array_merge( $term_ids, get_term_children( $term->term_id, 'product_cat' ) );
		}
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( $term_ids && has_term( $term_ids, 'product_cat', $item['product_id'] ) ) {
			return true;
		}
	}
	return false;
}

function perfectpixel_message_if_category_in_cart() {
	$slugs = array_filter( array_map( 'trim', explode( ',', '{{cart_category_slugs}}' ) ) );
	if ( perfectpixel_cart_has_category( $slugs ) ) {
		echo '<div class="woocommerce-info">' . wp_kses_post( '{{cart_category_message}}' ) . '</div>';
	}
}
